import React, { useState, useRef } from "react";
import { 
  X, User, Truck, AlertCircle, BookOpen, 
  Award, AlertTriangle, CheckCircle, Activity, MapPin 
} from "lucide-react";
import ScheduleTab from "../tabs/ScheduleTab";
import ReportsTab from "../tabs/ReportsTab";
import TrainingTab from "../tabs/TrainingTab";

// --- REUSABLE MODAL COMPONENT (Defined outside for cleanliness) ---
const ReportDetailModal = ({ report, onClose }) => (
  <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-[#47510B]/95 backdrop-blur-xl">
    <div className="bg-[#FDFAD8] w-full max-w-sm rounded-[50px] border-[8px] border-white overflow-hidden animate-slide-up shadow-2xl">
      <div className="h-48 w-full relative">
        <img src={report.img} alt="Evidence" className="w-full h-full object-cover" />
        <button onClick={onClose} className="absolute top-4 right-4 w-10 h-10 bg-white rounded-full flex items-center justify-center text-[#AB1717] shadow-xl border-2 border-[#AB1717]/10">
          <X size={20} />
        </button>
      </div>
      <div className="p-8">
        <h4 className="text-2xl font-black text-[#47510B] uppercase italic leading-none">{report.title}</h4>
        <div className="flex items-center gap-2 mt-2 mb-4 opacity-40 italic">
          <MapPin size={12} />
          <span className="text-[10px] font-black uppercase tracking-tighter">{report.loc}</span>
        </div>
        <p className="p-5 bg-white rounded-3xl border-2 border-[#47510B]/10 italic text-sm text-[#47510B]/80 mb-8 shadow-inner">
          "{report.description}"
        </p>
        <button onClick={onClose} className="w-full py-5 bg-[#47510B] text-[#CAD23C] rounded-[25px] font-black uppercase text-sm shadow-xl active:scale-95 transition-all">
          Mark as Resolved
        </button>
      </div>
    </div>
  </div>
);

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState("schedule");
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [selectedReport, setSelectedReport] = useState(null); // Added state
  const scrollRef = useRef(null);

  // Added Mock Data for Schedule Lookups
  const reportData = {
    'LOC_04': {
      id: 'REP-772',
      title: 'Waste Overflow',
      loc: 'Sector 4',
      citizen: 'A. Smith',
      description: 'The bin at the corner of 5th Ave is completely overflowing.',
      img: 'https://images.unsplash.com/photo-1605600611284-19561ad7ddf0?q=80&w=600',
    },
    'LOC_15': {
      id: 'REP-801',
      title: 'Illegal Dumping',
      loc: 'East Gate',
      citizen: 'P. Kumar',
      description: 'Debris left near the park entrance.',
      img: 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?q=80&w=600',
    }
  };

  const handleOpenReport = (locationId) => {
    setSelectedReport(reportData[locationId]);
  };

  const tabs = [
    { id: "schedule", label: "Tasks", icon: <Truck size={24} />, color: "#CAD23C" },
    { id: "reports", label: "Issues", icon: <AlertCircle size={24} />, color: "#AB1717" },
    { id: "training", label: "Learn", icon: <BookOpen size={24} />, color: "#A1AED1" },
  ];

  const scrollToTab = (tabId) => {
    const index = tabs.findIndex(t => t.id === tabId);
    setActiveTab(tabId);
    scrollRef.current.scrollTo({ left: index * window.innerWidth, behavior: "smooth" });
  };

  const handleScroll = () => {
    if (scrollRef.current) {
      const index = Math.round(scrollRef.current.scrollLeft / window.innerWidth);
      if (tabs[index] && tabs[index].id !== activeTab) {
        setActiveTab(tabs[index].id);
      }
    }
  };

  return (
    <div className="h-screen bg-[#FDFAD8] font-sans relative overflow-hidden perspective-1000">

      {/* --- REPORT DETAIL MODAL LAYER --- */}
      {selectedReport && (
        <ReportDetailModal 
          report={selectedReport} 
          onClose={() => setSelectedReport(null)} 
        />
      )}

      {/* --- PROFILE LAYER (READ-ONLY) --- */}
      {/* ... (Your existing profile layer code goes here) ... */}

      {/* --- DASHBOARD LAYER --- */}
      <div className={`h-full w-full transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex flex-col ${isProfileOpen ? "scale-50 opacity-0 -translate-x-full pointer-events-none" : "scale-100 opacity-100"}`}>
        <header className="fixed top-0 w-full max-w-[1100px] left-1/2 -translate-x-1/2 pt-10 px-8 flex justify-between items-center z-50">
          <h2 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tighter">{activeTab}<span className="text-[#CAD23C]">.</span></h2>
          <button onClick={() => setIsProfileOpen(true)} className="bg-[#47510B] p-1.5 pr-5 rounded-2xl flex items-center gap-3 border-2 border-white shadow-lg text-[#CAD23C] hover:scale-105 transition-all">
            <div className="w-9 h-9 rounded-xl bg-[#CAD23C] flex items-center justify-center text-[#47510B]"><User size={20} strokeWidth={3} /></div>
            <span className="font-black text-[11px] uppercase tracking-[0.2em]">Marcus.7729</span>
          </button>
        </header>

        <main ref={scrollRef} onScroll={handleScroll} className="flex-1 flex overflow-x-auto snap-x snap-mandatory no-scrollbar">
          <section className="min-w-full h-full snap-start flex items-center justify-center px-10">
            {/* Added handleOpenReport here */}
            <ScheduleTab onViewReport={handleOpenReport} />
          </section>
          <section className="min-w-full h-full snap-start flex items-center justify-center px-10">
            {/* Passed setSelectedReport for the Reports list view */}
            <ReportsTab onSelectReport={setSelectedReport} />
          </section>
          <section className="min-w-full h-full snap-start flex items-center justify-center px-10">
            <TrainingTab />
          </section>
        </main>

        <footer className="fixed bottom-12 left-1/2 -translate-x-1/2 z-50">
          <nav className="bg-[#47510B]/90 backdrop-blur-3xl border border-white/20 px-4 py-3.5 rounded-[40px] shadow-2xl flex items-center gap-3">
            {tabs.map((tab) => (
              <button key={tab.id} onClick={() => scrollToTab(tab.id)} className={`flex items-center gap-3 px-8 py-4 rounded-[30px] transition-all duration-500 group ${activeTab === tab.id ? "bg-[#CAD23C] shadow-xl scale-110" : "text-white/40 hover:text-white"}`}>
                <div style={{ color: activeTab === tab.id ? '#47510B' : 'inherit' }}>{tab.icon}</div>
                {activeTab === tab.id && <span className="text-[11px] font-[1000] uppercase tracking-widest text-[#47510B]">{tab.label}</span>}
              </button>
            ))}
          </nav>
        </footer>
      </div>
    </div>
  );
};

export default WorkerDashboard;
